import{_ as t,c as o,o as n,ag as a}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"React reference collections","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/frontend/react/index.md","filePath":"workbench/frontend/react/index.md"}'),r={name:"workbench/frontend/react/index.md"};function c(s,e,i,d,l,p){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="react-reference-collections" tabindex="-1">React reference collections <a class="header-anchor" href="#react-reference-collections" aria-label="Permalink to “React reference collections”">​</a></h1><p>React 19.3.0 and TypeScript 5.9.3. Copy this folder to an isolated directory, install its pinned package.json, and run <code>npm run build</code>; serve <code>output/</code> on loopback. <code>REFERENCE_MODE=production npm run build</code> produces the production variant. The root notes build does not bundle this application.</p><ul><li><code>composition/</code>: canonical slots/tabs, typed action adapter and negative type fixtures, included by the composition lesson.</li><li><code>forms/</code>: canonical date/reducer/wizard and note-query/mutation components. The browser demo uses the dependency-free wizard subset. The pinned manifest also permits strict checks of the React Hook Form/Query/Zod integrations; their real API/provider behavior remains separate practice.</li><li><code>design-system/</code>: Button/CSS Modules and token-generator references; CSS Modules need a compatible consumer bundler. The demo uses the native action adapter instead.</li><li><code>component-testing/</code>: a separate pinned three-test DOM/promise lab.</li><li><code>demo/</code>: state queues, keyed drafts, controlled ignored-abort race, tabs, native action and a local fake-save wizard under StrictMode.</li></ul><p>The fake save resolves locally and <strong>does not persist anything</strong>. The race adapter is a manually settled teaching port; production requests need finite deadlines. Never use this demo as an authenticated management screen.</p><p>See <a href="./../../../frontend/verification.html">author verification</a> for executed subsets. Apply <a href="./../../../practice/frontend/f05-react.html">F05</a> and the extracted lesson requirements yourself; all learner practice remains outstanding.</p><p><code>npm run typecheck</code> checks represented source/type fixtures; <code>npm run check:reference</code> checks pure/date/projection/mocked-response cases. <code>node design-system/check.mjs</code> checks token generation, not contrast or visual compatibility.</p>',6)])])}const m=t(r,[["render",c]]);export{h as __pageData,m as default};
